"""Helpers for interpreting jd's global and path-scoped JSON options."""

from __future__ import annotations

import math


def split_options(options):
    """Return (global option values, path option entries).

    A path option has the documented shape {"@": [...], "^": [...]}.
    Invalid entries are ignored here; CLI validation can report its own errors.
    """
    globals_ = []
    paths = []
    if not isinstance(options, list):
        return globals_, paths
    for item in options:
        if isinstance(item, dict) and isinstance(item.get("@"), list) and isinstance(item.get("^"), list):
            paths.append((item["@"], item["^"]))
        else:
            globals_.append(item)
    return globals_, paths


def options_at(options, path):
    """Resolve global settings and options targeted at exactly ``path``.

    Targeted options are applied after global options and in input order.
    Returns a flat option list, preserving option objects for downstream use.
    """
    globals_, paths = split_options(options)
    resolved = list(globals_)
    for target, values in paths:
        if len(target) == len(path) and all(a == b for a, b in zip(target, path)):
            resolved.extend(values)
    return resolved


def comparison_settings(options, path):
    """Return effective comparison flags at a JSON path.

    ``diff`` inherits from the nearest DIFF_ON/OFF ancestor. Comparison modes
    and precision use the most specific path declaration, falling back to
    global values.
    """
    globals_, path_entries = split_options(options)
    settings = {"mode": "list", "precision": 0.0, "setkeys": [], "diff": True}

    def apply(values):
        for item in values:
            if item == "SET":
                settings["mode"] = "set"
            elif item == "MULTISET":
                settings["mode"] = "multiset"
            elif item == "DIFF_OFF":
                settings["diff"] = False
            elif item == "DIFF_ON":
                settings["diff"] = True
            elif isinstance(item, dict):
                if isinstance(item.get("precision"), (int, float)) and not isinstance(item.get("precision"), bool):
                    settings["precision"] = float(item["precision"])
                if isinstance(item.get("setkeys"), list):
                    settings["setkeys"] = item["setkeys"]

    apply(globals_)
    # Apply matching ancestors from shallowest to deepest, preserving input
    # order among entries that target the same path.
    matching = [(len(target), idx, values) for idx, (target, values) in enumerate(path_entries)
                if len(target) <= len(path) and all(a == b for a, b in zip(target, path))]
    for _, _, values in sorted(matching, key=lambda x: (x[0], x[1])):
        apply(values)
    return settings


def numbers_equal(a, b, precision=0.0):
    """jd numeric comparison: absolute difference within configured precision."""
    if not isinstance(a, (int, float)) or isinstance(a, bool):
        return False
    if not isinstance(b, (int, float)) or isinstance(b, bool):
        return False
    return math.isclose(float(a), float(b), rel_tol=0.0, abs_tol=max(0.0, float(precision)))
"}

