"""Native jd-style structural diff rendering."""
import json
import math
from difflib import SequenceMatcher
from optionutil import comparison_settings


def _j(x):
    return json.dumps(x, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def diff_text(a, b, options=None):
    """Render a structural diff. ``options`` is an optional list of jd options."""
    options = options or []
    out = []

    def path(p):
        return "@ " + _j(p)

    def emit(p, old, new):
        out.append(path(p))
        if old is not _MISSING:
            out.append("- " + _j(old))
        if new is not _MISSING:
            out.append("+ " + _j(new))

    def walk(x, y, p):
        opts = comparison_settings(options, p)
        if not opts.get("diff", True):
            return
        if isinstance(x, (int, float)) and not isinstance(x, bool) and isinstance(y, (int, float)) and not isinstance(y, bool):
            if abs(float(x) - float(y)) <= opts.get("precision", 0):
                return
        elif type(x) is type(y) and x == y:
            return
        if isinstance(x, dict) and isinstance(y, dict):
            for k in sorted(set(x) | set(y)):
                if k in x and k in y:
                    walk(x[k], y[k], p + [k])
                elif k in x:
                    emit(p + [k], x[k], _MISSING)
                else:
                    emit(p + [k], _MISSING, y[k])
            return
        if isinstance(x, list) and isinstance(y, list):
            mode = opts.get("mode")
            if mode in ("set", "multiset"):
                xx, yy = list(x), list(y)
                if mode == "set":
                    sx, sy = set(map(_j, xx)), set(map(_j, yy))
                    xx = [v for v in xx if _j(v) in sx - sy]
                    yy = [v for v in yy if _j(v) in sy - sx]
                else:
                    # Keep stable order among remaining values while matching counts.
                    from collections import Counter
                    cx, cy = Counter(map(_j, xx)), Counter(map(_j, yy))
                    remx = {v: cx[v] - min(cx[v], cy[v]) for v in cx}
                    remy = {v: cy[v] - min(cx[v], cy[v]) for v in cy}
                    dx = [v for v in xx if remx[_j(v)] and not (remx.__setitem__(_j(v), remx[_j(v)]-1))]
                    dy = [v for v in yy if remy[_j(v)] and not (remy.__setitem__(_j(v), remy[_j(v)]-1))]
                    xx, yy = dx, dy
                if xx != yy:
                    emit(p + ([{}] if mode == "set" else [[]]), xx, yy)
                return
            # LCS-style edit blocks with one neighboring element on each side.
            sm = SequenceMatcher(a=[_j(v) for v in x], b=[_j(v) for v in y], autojunk=False)
            blocks = [z for z in sm.get_opcodes() if z[0] != "equal"]
            for tag, i1, i2, j1, j2 in blocks:
                start = max(0, i1 - 1)
                end = min(len(x), i2 + 1)
                out.append(path(p + [start]))
                for k in range(start, i1):
                    out.append("  " + _j(x[k]))
                for k in range(i1, i2):
                    out.append("- " + _j(x[k]))
                for k in range(j1, j2):
                    out.append("+ " + _j(y[k]))
                for k in range(i2, end):
                    out.append("  " + _j(x[k]))
            return
        emit(p, x, y)

    walk(a, b, [])
    if not out:
        return ""
    return "\n".join(out) + "\n"


def render_diff(a, b, opts=None):
    return diff_text(a, b, opts)


class _Missing: pass
_MISSING = _Missing()


def _opt(v):
    if isinstance(v, str):
        return {"mode": v} if v in ("SET", "MULTISET") else ({"off": True} if v == "DIFF_OFF" else {})
    if isinstance(v, dict):
        r = {}
        if isinstance(v.get("precision"), (int, float)):
            r["precision"] = v["precision"]
        if "setkeys" in v:
            r["setkeys"] = v["setkeys"]
        return r
    return {}
"}

