#!/usr/bin/env python3
"""Command line driver for the jd-compatible JSON diff implementation."""
from __future__ import annotations

import json
import os
import sys

VERSION = "jd version 2.5.0"


def _usage():
    return """Usage: jd [OPTION]... FILE1 [FILE2]
Diff and patch JSON files.

Prints the diff of FILE1 and FILE2 to STDOUT.
When FILE2 is omitted the second input is read from STDIN.
When patching (-p) FILE1 is a diff.

Options:
  -color       Print color diff.
  -color-words Print color diff with character-level highlighting.
  -p           Apply patch FILE1 to FILE2 or STDIN.
  -o=FILE3     Write to FILE3 instead of STDOUT.
  -opts='[]'   JSON array of comparison options.
  -set         Treat arrays as sets.
  -mset        Treat arrays as multisets.
  -setkeys     Keys to identify set objects.
  -yaml        Read and write YAML instead of JSON.
  -precision=N Maximum absolute difference for numbers to be equal.
  -f=FORMAT    Diff format: jd, patch, merge.
  -t=FORMATS   Translate formats, e.g. jd2patch or yaml2json.
