    """Apply jd ANSI conventions to an uncolored jd diff."""
    lines = rendered.splitlines(keepends=True)
    result = []
    paired = {}
    if words:
        i = 0
        while i < len(lines):
            if not lines[i].startswith(("- ", "+ ")):
                i += 1
                continue
            start = i
            while i < len(lines) and lines[i].startswith(("- ", "+ ")):
                i += 1
            removed = [j for j in range(start, i) if lines[j].startswith("- ")]
            added = [j for j in range(start, i) if lines[j].startswith("+ ")]
            paired.update(zip(removed, added))
